tool_input.command:
rm -f .claude/codemyrules/failures.log && node -e '
const fs=require("fs");const r={};
for (const f of fs.readdirSync("ast-grep/rules")) { const id=fs.readFileSync("ast-grep/rules/"+f,"utf8").match(/^id: (\S+)/m)[1]; r[id]=0; }
for (const l of fs.readFileSync("/tmp/cmr-hits.txt","utf8").trim().split("\n")) { const [id,n]=l.split(" "); r[id]=Number(n); }
for (const id of ["BLE001","LOG015","S602","S604","S605","S608","lint/style/noRestrictedGlobals","lint/nursery/noInlineStyles"]) r[id]=0;
r["lint/suspicious/noExplicitAny"]=2;
fs.writeFileSync("/tmp/cmr-loop/rules.json",JSON.stringify(r,null,1)); console.log(Object.keys(r).length, Object.values(r).reduce((a,b)=>a+b))' && node .claude/skills/codemyrules/scripts/measure.mjs baseline . --rules /tmp/cmr-loop/rules.json | tail -20
